import os
import glob

# 检查常见的可能数据位置
paths_to_check = [
    r"F:\qgis_project",
    r"F:\qgis_project\data",
    r"F:\data",
]

for base_path in paths_to_check:
    if os.path.exists(base_path):
        print(f"--- 目录: {base_path} ---")
        for f in os.listdir(base_path):
            if f.endswith(('.shp', '.gpkg', '.geojson', '.json', '.gpx', '.kml', '.tab', '.mif', '.dxf', '.dwg', '.csv', '.xlsx')):
                full_path = os.path.join(base_path, f)
                size = os.path.getsize(full_path)
                print(f"  {f} ({size} bytes)")
        # 也检查子目录
        for root, dirs, files in os.walk(base_path):
            for f in files:
                if f.endswith(('.shp', '.gpkg', '.geojson', '.json', '.gpx', '.kml')):
                    full_path = os.path.join(root, f)
                    size = os.path.getsize(full_path)
                    print(f"  {os.path.relpath(full_path, base_path)} ({size} bytes)")
    else:
        print(f"目录不存在: {base_path}")
